.checkout-submit {
  --brick-button-radius: var(--brick-radius-full);
  --brick-button-background: var(--brick-color-success-solid);
  --brick-button-background-hover: var(--brick-color-success-solid-hover);
  --brick-button-background-pressed: var(--brick-color-success-solid-pressed);
  --brick-button-foreground: var(--brick-color-success-on-solid);
  --brick-button-border-color: var(--brick-button-background);
}

.checkout-submit {
  inline-size: 100%;
}

@media (min-width: 48rem) {
  .checkout-submit {
    inline-size: auto;
  }
}

.product-preview {
  --brick-aspect-ratio-background: var(--brick-color-accent-subtle);
  --brick-aspect-ratio-border-color: var(--brick-color-accent-border);
  --brick-aspect-ratio-radius: 1rem;
}

.report-grid {
  display: grid;
  gap: 1rem;
}

@media (min-width: 48rem) {
  .report-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

[data-brick-theme="studio"] {
  --brick-color-accent-solid: #6d4aff;
  --brick-color-accent-on-solid: #ffffff;
  --brick-color-surface-canvas: #fbfaf8;
  --brick-radius-control: 0.625rem;
}

const [files, setFiles] = useState<File[]>([]);
const [rejected, setRejected] = useState("");

<FileUpload.Root
  accept="image/*"
  files={files}
  onFilesChange={setFiles}
  onRejectedFilesChange={(items) => setRejected(items[0]?.errors.join(", ") ?? "")}
>
  <FileUpload.HiddenInput />
  <FileUpload.Dropzone><FileUpload.Trigger>Select image</FileUpload.Trigger></FileUpload.Dropzone>
  <FileUpload.ItemGroup>{/* item anatomy */}</FileUpload.ItemGroup>
  <output aria-live="polite">{rejected}</output>
</FileUpload.Root>

const [openSide, setOpenSide] = useState<"start" | "end" | null>(null);

<SwipeableItem.Root openSide={openSide} onOpenSideChange={setOpenSide}>
  {/* labeled Actions and authored Content */}
</SwipeableItem.Root>

const [value, setValue] = useState("");

<Input
  aria-label="Project name"
  onValueChange={setValue}
  value={value}
/>;

const id = toast.loading("Uploading archive");
uploadArchive().then(
  () => toast.update(id, { title: "Upload complete", type: "success", duration: 5000 }),
  () => toast.update(id, { title: "Upload failed", type: "error", duration: Infinity }),
);

<Toaster width="full" stacking="overlap" swipeDirection="right" />;

const updates = [
  { id: "publish", title: "Release published", summary: "Version 2 is ready." },
  { id: "review", title: "Review requested", summary: "Morgan requested review." },
];

<Feed.Root aria-label="Release activity" setSize={updates.length}>
  {updates.map((update, index) => (
    <Feed.Item
      aria-describedby={`${update.id}-summary`}
      aria-labelledby={`${update.id}-title`}
      index={index}
      key={update.id}
    >
      <h2 id={`${update.id}-title`}>{update.title}</h2>
      <p id={`${update.id}-summary`}>{update.summary}</p>
    </Feed.Item>
  ))}
</Feed.Root>

export function App() {
  return <><Toaster /><button onClick={() => toast.success("Workspace saved")}>Save</button></>;
}

function CheckIcon() {
  return <svg fill="none" viewBox="0 0 20 20"><path d="m4 10 4 4 8-8" stroke="currentColor" /></svg>;
}

<Icon tone="success"><CheckIcon /></Icon>

